describe("Procurement purchase-to-payment progress", () => {
  it("requires all receipts and invoices to complete their owning stages", () => {
    expect(projectPurchaseProgress(request, facts, true, true).completed).toBe(6);
    const result = projectPurchaseProgress(request, { ...facts, bills: { ...facts.bills, matched_receipt_count: 1, paid_count: 0 } }, true, true);
    expect(result.steps.find(x => x.id === "invoice")?.state).toBe("current"); expect(result.steps.find(x => x.id === "payment")?.state).toBe("current"); expect(result.completed).toBe(4);
  });
  it("omits foreign-owner links when the selected assignment lacks that authority", () => {
    expect(projectPurchaseProgress(request, facts, false, false).steps.every(x => x.href === null)).toBe(true);
    expect(projectPurchaseProgress(request, facts, true, true).steps.find(x => x.id === "payment")?.href).toBe("/finance/supplier-batches/batch");
  });
  it("keeps Records authorization before projection reads and refuses another request kind", async () => {
    const readFacts = vi.fn(async () => facts), ports = { canPurchase: true, canFinance: false, request: vi.fn(async () => { throw new Error("request revoked"); }), facts: readFacts };
    await expect(createPurchaseProgressApplication(ports)("request")).rejects.toThrow("request revoked"); expect(readFacts).not.toHaveBeenCalled();
    await expect(createPurchaseProgressApplication({ ...ports, request: async () => ({ ...request, kind: "leave" }) })("request")).rejects.toMatchObject({ code: "PURCHASE_REQUEST_REQUIRED" }); expect(readFacts).not.toHaveBeenCalled();
  });
});

